dtsPropsFor.Icon:
/** One of the vendored Phosphor glyphs: `caretDown`, `close`, `more`, `list`, `search`, `upload`. Add a glyph in source, never by a package. */
  name: 'caretDown' | 'close' | 'more' | 'list' | 'search' | 'upload';
  /** Pixels. 16 by default, where Phosphor's regular weight is a one-pixel line. Always `aria-hidden`: put it inside a control that carries its own label. */
  size?: number;

dtsPropsFor.Menu:
/** Unique on the page: the popover's id and its anchor name. */
  id: string;
  /** The button's text, and its accessible name when `icon` replaces it. */
  label: string;
  /** Shown instead of the label. */
  icon?: 'caretDown' | 'close' | 'more' | 'list' | 'search' | 'upload';
  /** The panel's contents: a column of controls, 12px apart. The panel is 16rem, Machined Slate, overlay shadow. */
  children: React.ReactNode;

dtsPropsFor.Dialog:
/** Heading text. Also the dialog's accessible name, via `aria-labelledby`. */
  title: string;
  /** Escape, a click on the scrim, and the close button all call this. */
  onClose: () => void;
  /** The body. `Dialog` renders the scrim, panel, title row and close button — everything below the title is the caller's. */
  children: React.ReactNode;
  /** `stage` is most of the window, for a part in 3D (the Space stage). */
  size?: 'default' | 'stage';
  /** Where focus goes on close, when not to whatever opened it. */
  returnFocus?: () => HTMLElement | null;

dtsPropsFor.Grid:
parts: ReadonlyArray<{
    id: string; library: string; revision: string;
    name: string; partNumber: string | null; sourcePath: string;
    /** `data:image/webp;base64,...` with alpha — the render inset in the card's well — or null. */
    thumbnail: string | null;
    triangleCount: number | null;
    /** True when any figure is mesh-derived; the card then says "approximate". Always label it. */
    approximate: boolean;
    sourceHash: string | null; tessellationL0: string | null;
    sourceBytes: number | null; storedBytes: number | null; compressed: boolean | null;
    /** `libraries/default/Terrain/rock` — shown, selectable, never a link. */
    directory: string | null; storagePath: string | null;
    createdAt: string; updatedAt: string; removedAt: string | null;
  }>;
  /** Reflow by whole tiles: `minmax(11rem, 1fr)` with 16px gutters, or `minmax(8rem, 1fr)` with 12px. */
  density: 'comfortable' | 'compact';
  layout: 'detail' | 'gallery' | 'list';
  /** Picking parts: every card shows a checkbox. */
  selecting: boolean;
  selected: ReadonlySet<string>;
  onToggle: (part: string, range: boolean) => void;
  onSelectAll: () => void;
  onOpen: (part: object, from: DOMRect) => void;
  onHover: (part: object) => void;
  onRender: (part: string) => void;
  /** The part whose preview is rendering now. */
  busyPart?: string;
  /** Where the store is on the host, prefixed to storage paths when known. */
  hostRoot: string | null;
  /** Whether a resting pointer turns a card's part in 3D. Off in a design. */
  spins?: boolean;
  onLook?: (part: object, from: DOMRect) => void;

dtsPropsFor.SelectionBar:
/** How many parts are picked. */
  count: number;
  /** A bulk move or removal under way, or null. */
  bulk: { done: number; total: number; failures: { id: string; name: string; reason: string }[] } | null;
  onMove: () => void;
  onRemove: () => void;
  onExport: () => void;
  /** What the last export said, or null. */
  note: string | null;
  onClear: () => void;

dtsPropsFor.Figure:
/** A measured value and whether it is mesh-derived. An approximate one is labelled "approximate" — never drop the label. */
  figure: { value: unknown; approximate: boolean };
  /** Formats the value: mono, tabular, with units, e.g. `(mm) => mm.toFixed(1) + ' mm'`. */
  render: (value: unknown) => string;

dtsPropsFor.MeasureBar:
/** The pressed tool, or null. A pressed tool takes a Layout Blue edge. */
  tool: 'distance' | 'edge' | 'diameter' | 'angle' | 'wall' | null;
  onTool: (tool: 'distance' | 'edge' | 'diameter' | 'angle' | 'wall' | null) => void;
  /** The reading, mono, with "approximate" when mesh-derived. */
  reading: { value: number; approximate: boolean } | null;
  /** What to do next, shown while there is no reading. */
  note: string | null;
  /** Why measuring is off; no tool can be picked while it is set. */
  off?: string | null;

dtsPropsFor.SectionBar:
/** The cut, or null for none: an axis, where along it, and which side is kept. */
  section: { axis: 'x' | 'y' | 'z'; at: number; flip: boolean } | null;
  onSection: (section: { axis: 'x' | 'y' | 'z'; at: number; flip: boolean } | null) => void;
  /** Whether the part is a closed mesh; null when nobody measured. Only a closed one's cut is filled. */
  closed: boolean | null;

dtsPropsFor.AppFrame:
/** The place this page is: the places switch raises it. */
  current?: 'parts' | 'removed' | 'sharing';
  /** The library the places carry, so leaving and coming back keeps it. */
  library?: string;
  /** The content's anchor, for the skip link. */
  skipTo?: { href: string; label: string };
  /** The page's own search. Absent: a search that takes you to the grid. `null`: none. */
  search?: React.ReactNode | null;
  /** The page's actions, right of search — Upload and the Library menu on the parts page. */
  actions?: React.ReactNode;
  /** The category rail: beside the content from `md`, a drawer under it. */
  rail?: React.ReactNode;
  /** Off only for the crash page. */
  nav?: boolean;
  children: React.ReactNode;

dtsPropsFor.Card:
part: {
    id: string; library: string; revision: string;
    name: string; partNumber: string | null; sourcePath: string;
    /** `data:image/webp;base64,...` with alpha — the render inset in the card's well — or null. */
    thumbnail: string | null;
    triangleCount: number | null;
    /** True when any figure is mesh-derived; the card then says "approximate". Always label it. */
    approximate: boolean;
    sourceHash: string | null; tessellationL0: string | null;
    sourceBytes: number | null; storedBytes: number | null; compressed: boolean | null;
    /** `libraries/default/Terrain/rock` — shown, selectable, never a link. */
    directory: string | null; storagePath: string | null;
    createdAt: string; updatedAt: string; removedAt: string | null;
  };
  /** Card layout: square inset well with name and figures below; render filling the card under a dark foot; one list row. */
  layout: 'detail' | 'gallery' | 'list';
  selecting: boolean;
  /** Picked: a 2px Layout Blue outline. */
  selected: boolean;
  /** This card's preview is rendering. */
  busy: boolean;
  hostRoot: string | null;
  onRender: (part: string) => void;
  onToggle: (part: string, range: boolean) => void;
  onOpen: (part: object, from: DOMRect) => void;
  onHover: (part: object) => void;
  /** Whether a resting pointer turns the part in 3D. Off in a design. */
  spins?: boolean;
  onLook?: (part: object, from: DOMRect) => void;

dtsPropsFor.FolderTree:
/** Library whose category tree is shown. Reads `['folders', library]` — seed it through `DesignProviders` to draw rows. */
  library: string;
  /** The selected category, or `null` for the whole library. */
  selected: string | null;
  /** Fired when a row is chosen. `null` means the selection was cleared. */
  onSelect: (folder: string | null) => void;

dtsPropsFor.MovePartDialog:
/** The part being moved. */
  part: { id: string; name: string };
  /** The library the move happens within. Moves never cross libraries. */
  library: string;
  /** Called on cancel and after a completed move. */
  onClose: () => void;

dtsPropsFor.Detail:
/** One part's full record, exactly as `GET /api/parts/{id}` returns it (the ts-rs `PartDetail`): identity (id, library, revision, revLabel, name, partNumber, sourcePath), what people recorded (tags, materials, custom fields), geometry (triangleCount, isWatertight, bboxMm, volumeMm3, surfaceAreaMm2 — each `{ value, approximate }`, and an approximate one must be labelled), the file (sourceFormat, sourceBytes, storedBytes, sourceHash, directory, storagePath), derivative hashes, lock, sharedBy, createdAt, updatedAt. */
  part: object;
  /** Controls for the header. The part page passes Download and the ⋯ menu; the quick look passes none. */
  actions?: React.ReactNode;
  /** Whether the record-a-source form is offered. Off in the quick look, on for the full page. */
  recordable?: boolean;
  /** Whether something around it already names the part (the quick look's dialog title). */
  titled?: boolean;
  /** `panel` in the quick look; `page` is the part's own page, laid out as a studio. */
  layout?: 'panel' | 'page';

dtsPropsFor.ShareDialog:
/** The library the category is in. */
  library: string;
  /** The category to share: `{ id, parentId, name, slug, partCount }`. */
  folder: { id: string; parentId: string | null; name: string; slug: string; partCount: number };
  /** Already shared: the dialog then keeps who it goes to rather than widening it, and says so. */
  alreadyShared: boolean;
  onClose: () => void;
